    scale = float(hp.get('scale', 1.8))
    cost_coef = float(hp.get('cost_coef', 0.14))
    gap_clip = float(hp.get('gap_clip', 20.0))
    logit_clip = float(hp.get('logit_clip', 12.0))
    eps = float(hp.get('eps', 1e-6))

    # Pull tensors from batch first, then model_output; final fallback uses zeros_like for shape safety.
    lpw = batch.get('log_prob_w', None)
    lpl = batch.get('log_prob_l', None)
    if lpw is None and isinstance(model_output, dict):
        lpw = model_output.get('log_prob_w', None)
    if lpl is None and isinstance(model_output, dict):
        lpl = model_output.get('log_prob_l', None)

    cost_a = batch.get('cost_a', None)
    cost_b = batch.get('cost_b', None)
    if cost_a is None and isinstance(model_output, dict):
        cost_a = model_output.get('cost_a', None)
    if cost_b is None and isinstance(model_output, dict):
        cost_b = model_output.get('cost_b', None)

    base = cost_a
    if base is None:
        base = cost_b
    if base is None:
        base = lpw
    if base is None:
        base = lpl

    if lpw is None:
        lpw = ops.zeros_like(base)
    if lpl is None:
        lpl = ops.zeros_like(lpw)
    if cost_a is None:
        cost_a = ops.zeros_like(lpw)
    if cost_b is None:
        cost_b = ops.zeros_like(lpw)

    pref = alpha * scale * (lpw - lpl)
    gap = (cost_b - cost_a).detach()
    gap = ops.clamp(gap, -gap_clip, gap_clip)

    x = pref - cost_coef * gap
    x = ops.clamp(x, -logit_clip, logit_clip)

    loss = -ops.logsigmoid(x)

    w = batch.get('weight', None)
    if w is None and isinstance(model_output, dict):
        w = model_output.get('weight', None)

    if w is not None:
        w = ops.clamp(w, 0.0, 1e9)
        denom = ops.clamp(w.mean(), eps, 1e9)
        return (loss * w).sum() / denom

    return loss.mean()

